import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.BefGvJmu.js";const m=JSON.parse('{"title":"PAI Content Protocol — Draft 1","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md"}'),s={name:"spec/index.md"};function o(r,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="pai-content-protocol-—-draft-1" tabindex="-1">PAI Content Protocol — Draft 1 <a class="header-anchor" href="#pai-content-protocol-—-draft-1" aria-label="Permalink to &quot;PAI Content Protocol — Draft 1&quot;">​</a></h1><p>2026-11-09 · Protocol <code>0.1.0-draft.1</code> · Content model <code>0.6</code> · ZIP packaging <code>1</code></p><p>PAI defines how clients and servers publish, update, and retrieve content. A personal AI application can use a PAI client to upload a document to a selected service. Other clients can retrieve its text, original images, and version-specific source URLs. A service provider operates a PAI server; Follo is one possible provider.</p><p>This draft specifies content publication and retrieval. It provides document, version, block, and asset identifiers for later retrieval extensions. Hosted-agent interactions will be specified separately.</p><h2 id="document-representations" tabindex="-1">Document representations <a class="header-anchor" href="#document-representations" aria-label="Permalink to &quot;Document representations&quot;">​</a></h2><p>A PAI document contains text, layout, images, and document metadata. It has two file representations:</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th><th>Use</th></tr></thead><tbody><tr><td><code>.pai</code></td><td>Document data and original images in a ZIP container</td><td>Storage, upload, download, and processing by compatible tools</td></tr><tr><td><code>.pai.html</code></td><td>The same document plus a rendering and editing runtime</td><td>Standalone distribution and offline browser editing</td></tr></tbody></table><p>Conversion preserves document identity, revision, text, layout, and original image bytes. An online service can store the same content in a database and asset store, then construct a file when requested.</p><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h2><ul><li><a href="/pai-website/spec/terminology.html">Terminology</a> defines clients, servers, publishers, documents, and publication versions.</li><li><a href="/pai-website/spec/format.html">Content model and file packaging</a> defines document fields, Markdown extensions, assets, and both containers.</li><li><a href="/pai-website/spec/service.html">Content service</a> defines discovery, authentication, publication, updates, and retrieval.</li><li><a href="/pai-website/spec/hash.html">Content hashing</a> defines the packaging-independent digest and legacy hash handling.</li></ul><p>The <a href="/pai-website/spec/schemas/">JSON Schemas</a> use JSON Schema 2020-12. The <a href="/pai-website/spec/fixtures/">fixtures</a> provide documents, files, hash results, and request/response examples. Schema validation covers field shapes and values. Implementations also need the cross-field, container, and behavioral checks defined in these specifications.</p><h2 id="conformance-language" tabindex="-1">Conformance language <a class="header-anchor" href="#conformance-language" aria-label="Permalink to &quot;Conformance language&quot;">​</a></h2><p>The uppercase terms <strong>MUST</strong>, <strong>MUST NOT</strong>, <strong>REQUIRED</strong>, <strong>SHOULD</strong>, <strong>SHOULD NOT</strong>, <strong>MAY</strong>, and <strong>OPTIONAL</strong> express the requirement levels defined by BCP 14, <a href="https://www.rfc-editor.org/rfc/rfc2119.html" target="_blank" rel="noreferrer">RFC 2119</a> and <a href="https://www.rfc-editor.org/rfc/rfc8174.html" target="_blank" rel="noreferrer">RFC 8174</a>. Lowercase uses have their ordinary meaning.</p><p>Field definitions, constraints, and operation rules in FORMAT, SERVICE, and HASH are normative. Examples, explanations, historical notes, and sections labeled <strong>Implementation note</strong> are informative. Implementation limits describe the reference tools and do not establish universal protocol limits. Example domains and credentials are placeholders.</p><h2 id="implementation-status" tabindex="-1">Implementation status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to &quot;Implementation status&quot;">​</a></h2><p>The reference file tools, browser editor, and content service implement this draft. Installation and integration guides describe their current behavior. Development reports and independent tester instructions are in <a href="https://github.com/JacenDu/pai-protocol/blob/main/development/README.md" target="_blank" rel="noreferrer">development/</a>. This draft remains under development.</p><p>Run the fixture checks from the project root, containing <code>package.json</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:spec</span></span></code></pre></div><p>The checks use Node.js, Ajv, and Python 3. Python independently opens the fixed ZIP samples and verifies entries and image bytes. See the <a href="https://github.com/JacenDu/pai-protocol/blob/main/README.md" target="_blank" rel="noreferrer">project README</a> for installation and the <a href="/pai-website/guide/file-tools.html">file tools</a> for file operations.</p>`,19)])])}const f=t(s,[["render",o]]);export{m as __pageData,f as default};
